// Achata /me/adaccounts. `account_id` e o numero puro, que e o que
// ads_conta.conta_id guarda — `id` vem como 'act_<numero>' e nao serve.
const rows = [];
for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error) continue;
  for (const a of (body.data || [])) {
    rows.push({
      conta_id: String(a.account_id || String(a.id || '').replace('act_', '')),
      nome: a.name || null,
      moeda: a.currency || null,
      timezone: a.timezone_name || null,
      status_meta: a.account_status === undefined ? null : Number(a.account_status),
    });
  }
}
return [{ json: { total: rows.length, payload: JSON.stringify(rows) } }];

// Achata /me/accounts. Uma Pagina pode nao ter Instagram vinculado — foi o
// caso da pagina Finamob na varredura de 03/09. Essas sao ignoradas: o que
// interessa aqui e o perfil, nao a Pagina.
const rows = [];
let paginas = 0, sem_ig = 0;
for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error) continue;
  for (const p of (body.data || [])) {
    paginas++;
    const ig = p.instagram_business_account;
    if (!ig || !ig.id) { sem_ig++; continue; }
    rows.push({
      perfil_id: String(ig.id),
      username: ig.username || null,
      nome: p.name || ig.name || null,     // o nome da Pagina e mais legivel
      page_id: String(p.id),
    });
  }
}
return [{ json: {
  total: rows.length, paginas_vistas: paginas, paginas_sem_instagram: sem_ig,
  payload: JSON.stringify(rows),
} }];

// Junta os dois upserts num aviso unico, e decide se vale mandar.
//
// Novos sao auto-limitantes: a linha e inserida uma vez, entao o aviso sai
// uma vez. `sumidos` seriam ruido diario, por isso o SQL so devolve os que
// estao com EXATAMENTE 3 dias sem aparecer — dispara uma vez, tres dias
// depois, o que filtra soluco de API sem esconder desvinculo de verdade.
const c = $('Upsert Contas').first().json  || {};
const p = $('Upsert Perfis').first().json  || {};

const nc = c.novos  || [];
const np = p.novos  || [];
const sc = c.sumidos || [];
const sp = p.sumidos || [];

const linhas = [];

if (nc.length) {
  linhas.push('*Contas de anuncio novas*');
  for (const x of nc) linhas.push('- ' + x.nome + '  `' + x.conta_id + '`');
  linhas.push('');
}
if (np.length) {
  linhas.push('*Perfis de Instagram novos*');
  for (const x of np) linhas.push('- @' + x.username + '  `' + x.perfil_id + '`');
  linhas.push('');
}
if (sc.length || sp.length) {
  linhas.push('*Sumiram da API ha 3 dias*');
  for (const x of sc) linhas.push('- conta ' + x.nome + '  `' + x.conta_id + '`');
  for (const x of sp) linhas.push('- perfil @' + x.username + '  `' + x.perfil_id + '`');
  linhas.push('');
}

const novidade = nc.length + np.length + sc.length + sp.length;

if (nc.length || np.length) {
  linhas.push('_Ja estao coletando (`ativo = true`) e NAO entram em report '
            + '(`reportar = false`). Falta definir o `cliente`: estao como '
            + '`a_classificar` em `vw_ads_a_classificar`._');
}
if (sc.length || sp.length) {
  linhas.push('_Nada foi desativado. Se o desvinculo foi de proposito, '
            + '`ativo = false` na mao._');
}

return [{ json: {
  novidade,
  novas_contas: nc.length, novos_perfis: np.length,
  sumidos: sc.length + sp.length,
  texto: linhas.join('\n'),
} }];

